    #[value(default, skip_serializing_if = "Vec::is_empty")]
    pub modified: Vec<PdfIndexedItem<T>>,
    #[value(default, skip_serializing_if = "Vec::is_empty")]
    pub added: Vec<PdfIndexedItem<T>>,
