/// 🆔 An id-keyed triple of whole values (the document collections keyed by `id`/`name`).
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub struct PdfKeyedItem<T> {
