/// 🗂️ Installs `/Root/DPartRoot` over one `/Type /DPart` node, carrying `/DPM << /Job … >>` when
/// `job` is non-empty — ISO 16612-2's variable-data partitioning in its minimal legitimate form.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
/// 🌲️ Admits the real retained page tree before any partition graph allocation.
pub fn admitted_first_page(snapshot: &PdfSnapshot) -> Option<ObjRef> {
    fn entry<'a>(value: &'a PdfObject, key: &str) -> Option<&'a PdfObject> {
        let entries = match value { PdfObject::Dict(entries) => entries, _ => return None };
        let mut values = entries.iter().filter(|entry| entry.key == key);
        let value = &values.next()?.value;
        if values.next().is_some() { return None; }
        Some(value)
    }
    fn admitted_object(snapshot: &PdfSnapshot, reference: ObjRef) -> Option<&PdfObject> {
        let mut values = snapshot.objects.iter().filter(|object| object.id == reference);
        let value = &values.next()?.value;
        if values.next().is_some() { return None; }
        Some(value)
    }
    fn inherited_media<'a>(snapshot: &'a PdfSnapshot, mut reference: ObjRef) -> Option<&'a [PdfObject]> {
        let mut seen = std::collections::HashSet::new();
        loop {
            if !seen.insert(reference) { return None; }
            let PdfObject::Dict(entries) = admitted_object(snapshot, reference)? else { return None; };
            let mut values = entries.iter().filter(|entry| entry.key == "MediaBox");
            if let Some(value) = values.next() { if values.next().is_some() { return None; } return value.value.as_array(); }
            reference = entry(admitted_object(snapshot, reference)?, "Parent")?.as_ref()?;
        }
    }
    let roots = snapshot.trailer.iter().filter(|entry| entry.key == "Root").collect::<Vec<_>>();
    if roots.len() != 1 { return None; }
    let catalog = admitted_object(snapshot, roots[0].value.as_ref()?)?;
    if entry(catalog, "Type")?.as_name() != Some("Catalog") { return None; }
    let tree = entry(catalog, "Pages")?.as_ref()?;
    if entry(admitted_object(snapshot, tree)?, "Type")?.as_name() != Some("Pages") { return None; }
    let mut leaves = Vec::new();
    let mut pending = vec![(tree, None, false)];
    let mut seen = std::collections::HashSet::new();
    let mut counts = std::collections::HashMap::<ObjRef, usize>::new();
    while let Some((reference, parent, finishing)) = pending.pop() {
        let value = admitted_object(snapshot, reference)?;
        let kind = entry(value, "Type")?.as_name()?;
        if finishing {
            let mut count = 0usize;
            for child in entry(value, "Kids")?.as_array()? { count = count.checked_add(*counts.get(&child.as_ref()?)?)?; }
            let PdfObject::Int(declared) = entry(value, "Count")? else { return None; };
            if *declared != i64::try_from(count).ok()? { return None; }
            counts.insert(reference, count);
            continue;
        }
        if !seen.insert(reference) { return None; }
        if let Some(parent) = parent { if entry(value, "Parent")?.as_ref()? != parent { return None; } }
        match kind {
            "Page" => { leaves.push(reference); counts.insert(reference, 1); }
            "Pages" => {
                pending.push((reference, parent, true));
                for child in entry(value, "Kids")?.as_array()?.iter().rev() { pending.push((child.as_ref()?, Some(reference), false)); }
            }
            _ => return None,
        }
    }
    if leaves.len() != snapshot.pages.len() { return None; }
    for (reference, typed) in leaves.iter().zip(&snapshot.pages) {
        let media = inherited_media(snapshot, *reference)?;
        if media.len() != 4 { return None; }
        for (raw, expected) in media.iter().zip(&typed.media_box) {
            let number = match raw {
                PdfObject::Int(value) => *value as f64,
                PdfObject::Real(value) => format!("{}{}e-{}", if value.negative { "-" } else { "" }, value.coefficient, value.scale).parse::<f64>().ok()?,
                _ => return None,
            };
            if number.to_bits() != expected.to_bits() { return None; }
        }
    }
    leaves.first().copied()
}

pub fn set_dpart_root(snapshot: &mut PdfSnapshot, job: &str) -> bool {
    let Some(page) = admitted_first_page(snapshot) else { return false; };
    if snapshot.objects.iter().map(|object| object.id.num).max().unwrap_or(0).checked_add(2).is_none() { return false; }
    let mut node = vec![("Type", PdfObject::Name("DPart".to_string())), ("Start", PdfObject::Ref(page))];
    if !job.is_empty() { node.push(("DPM", single_entry_dict("Job", literal(job)))); }
    let node_id = insert_object(snapshot, dict(node));
    let root = insert_object(snapshot, dict(vec![("Type", PdfObject::Name("DPartRoot".to_string())), ("DPartRootNode", PdfObject::Ref(node_id))]));
    set_entry(snapshot, node_id, "Parent", PdfObject::Ref(root));
    let catalog = snapshot.trailer.iter().find(|entry| entry.key == "Root").and_then(|entry| entry.value.as_ref()).expect("admitted catalog reference");
    set_entry(snapshot, catalog, "DPartRoot", PdfObject::Ref(root));
    if let Some(entry) = snapshot.catalog_extra.iter_mut().find(|entry| entry.key == "DPartRoot") { entry.value = PdfObject::Ref(root); }
    else { snapshot.catalog_extra.push(PdfDictEntry::new("DPartRoot", PdfObject::Ref(root))); }
    true
}

/// 🗂️ Rewrites the root `/DPart` node's `/DPM`, or drops it when `job` is `None`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn set_dpart_job(snapshot: &mut PdfSnapshot, job: Option<&str>) {
    let Some(node) = dpart_root_node(snapshot) else { return };
    match job {
        Some(value) => set_entry(snapshot, node, "DPM", single_entry_dict("Job", literal(value))),
        None => remove_entry(snapshot, node, "DPM"),
    }
}

/// 📄️ The `/Type /Page` objects, in retained order — the ordinal space `/TrimBox` is addressed in.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn page_objects(snapshot: &PdfSnapshot) -> Vec<ObjRef> {
    find_objects(snapshot, |value| dict_name(value, "Type") == Some("Page"))
}

/// 📄️ One page's `/TrimBox` (or `/ArtBox`) as four numbers.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn page_box(snapshot: &PdfSnapshot, page: ObjRef, key: &str) -> Option<[f64; 4]> {
    let items = object(snapshot, page)?.dict_get(key)?.as_array()?;
    if items.len() != 4 {
        return None;
    }
    let values: Vec<f64> = items.iter().map(|item| item.as_f64().unwrap_or(0.0)).collect();
    Some([values[0], values[1], values[2], values[3]])
}

/// 📄️ A four-number box array in PDF's own real-number form.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn box_object(values: [f64; 4]) -> PdfObject {
    PdfObject::Array(values.iter().map(|value| PdfObject::Real((*value).into())).collect())
}
