/** 🌲️ Retained Catalog/Pages admission and exact owned partition edits. */
import type { PdfSnapshot, PdfObject, ObjRef, PdfDictEntry } from '../📸️snapshot/🟦️.ts';
import type { PdfRawGraph } from '../🔺️diff/🟦️.ts';
import { binary64 } from '../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🔢️ieee754/🟦️.ts';
const validReference=(reference:ObjRef)=>Number.isInteger(reference.num)&&reference.num>=0&&reference.num<=0xffffffff&&Number.isInteger(reference.gen)&&reference.gen>=0&&reference.gen<=65535;
const key=(reference:ObjRef)=>`${reference.num}:${reference.gen}`;
function entry(value:PdfObject|undefined,name:string):PdfObject|undefined {if(value?.kind!=='dict')return;const matches=value.value.filter(entry=>entry.key===name);return matches.length===1?matches[0]!.value:undefined;}
function reference(value:PdfObject|undefined):ObjRef|undefined {return value?.kind==='ref'&&validReference(value)?{num:value.num,gen:value.gen}:undefined;}
/** 🌲️ Walks the actual retained Root tree iteratively and refuses cycles, duplicate roles and inconsistent page owners. */
export function admittedFirstPage(snapshot:PdfSnapshot):ObjRef|undefined {
  const objects=new Map<string,PdfObject|undefined>();for(const object of snapshot.objects){if(!validReference(object.id))return;const identity=key(object.id);objects.set(identity,objects.has(identity)?undefined:object.value);}
  const roots=snapshot.trailer.filter(entry=>entry.key==='Root');if(roots.length!==1)return;const root=reference(roots[0]!.value);if(!root)return;const catalog=objects.get(key(root));const type=entry(catalog,'Type');if(type?.kind!=='name'||type.value!=='Catalog')return;
  const tree=reference(entry(catalog,'Pages'));if(!tree)return;const treeType=entry(objects.get(key(tree)),'Type');if(treeType?.kind!=='name'||treeType.value!=='Pages')return;
  const pending:{reference:ObjRef;parent?:ObjRef;finishing:boolean}[]=[{reference:tree,finishing:false}],seen=new Set<string>(),counts=new Map<string,bigint>(),leaves:ObjRef[]=[];
  while(pending.length){const frame=pending.pop()!,identity=key(frame.reference),value=objects.get(identity),kind=entry(value,'Type');if(kind?.kind!=='name')return;
    if(frame.finishing){const kids=entry(value,'Kids'),count=entry(value,'Count');if(kids?.kind!=='array'||count?.kind!=='int')return;let total=0n;for(const child of kids.value){const childRef=reference(child);if(!childRef)return;const subcount=counts.get(key(childRef));if(subcount===undefined)return;total+=subcount;}if(count.value!==total)return;counts.set(identity,total);continue;}
    if(seen.has(identity))return;seen.add(identity);if(frame.parent){const parent=reference(entry(value,'Parent'));if(!parent||key(parent)!==key(frame.parent))return;}
    if(kind.value==='Page'){leaves.push(frame.reference);counts.set(identity,1n);}else if(kind.value==='Pages'){const kids=entry(value,'Kids');if(kids?.kind!=='array')return;pending.push({...frame,finishing:true});for(const child of [...kids.value].reverse()){const childRef=reference(child);if(!childRef)return;pending.push({reference:childRef,parent:frame.reference,finishing:false});}}else return;
  }
  function inheritedMedia(reference:ObjRef):PdfObject|undefined {const visited=new Set<string>();while(true){const identity=key(reference);if(visited.has(identity))return;visited.add(identity);const value=objects.get(identity);if(value?.kind!=='dict')return;const values=value.value.filter(entry=>entry.key==='MediaBox');if(values.length>1)return;if(values.length===1)return values[0]!.value;const parent=referenceOfParent(value);if(!parent)return;reference=parent;}}
  function referenceOfParent(value:PdfObject):ObjRef|undefined {return reference(entry(value,'Parent'));}
  if(leaves.length!==snapshot.pages.length)return;
  for(let index=0;index<leaves.length;index++){const media=inheritedMedia(leaves[index]!);if(media?.kind!=='array'||media.value.length!==4)return;for(let axis=0;axis<4;axis++){const value=media.value[axis]!;let number:number;if(value.kind==='int')number=Number(value.value);else if(value.kind==='real'&&/^[0-9]+$/.test(value.coefficient))number=Number(`${value.negative?'-':''}${value.coefficient}e-${value.scale}`);else return;if(binary64(number).bits!==snapshot.pages[index]!.mediaBox[axis]!.bits)return;}}
