use super::*;
use protocol::MutationDiff;

#[test]
fn changes_the_owned_conformance_axis_and_plans_its_inverse() {
    let mut base = PdfSnapshot::default();
    let catalog = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Catalog".to_string()))]));
    base.trailer.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfDictEntry::new("Root", PdfObject::Ref(catalog)));
    let pages = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Pages".into())), ("Count", PdfObject::Int(1))]));
    let page = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Page".into())), ("Parent", PdfObject::Ref(pages)), ("MediaBox", PdfObject::numbers(&[0.0, 0.0, 100.0, 100.0]))]));
    support::set_entry(&mut base, catalog, "Pages", PdfObject::Ref(pages));
    support::set_entry(&mut base, pages, "Kids", PdfObject::Array(vec![PdfObject::Ref(page)]));
    base.pages.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfPage::new(100.0, 100.0));
    let mutation = SetDpartRoot { job: "run 4711".to_string() };
    let outcome = <SetDpartRoot as MutationKind<PdfSnapshot, PdfVtMutation>>::diff(&mutation, &base);
    let next = outcome.diff().apply(&base).unwrap();
    assert!(support::catalog_entry(&next, "DPartRoot").is_some());
    assert_eq!(support::dpart_job(&next).as_deref(), Some("run 4711"));
    let inverse = <SetDpartRoot as MutationKind<PdfSnapshot, PdfVtMutation>>::inverse(&mutation, &base).expect("valid retained mutation inverse fixture");
    assert!(matches!(inverse.as_slice(), [PdfVtMutation::RestoreDpartGraph(_)]));
    let PdfVtMutation::RestoreDpartGraph(restore) = &inverse[0] else { unreachable!() };
    let undo = <super::super::RestoreDpartGraph as MutationKind<PdfSnapshot, PdfVtMutation>>::diff(restore, &next);
    let restored = undo.diff().apply(&next).unwrap();
    assert_eq!(restored, base);
}

