    const failures: string[] = [];
    for (const kind of KINDS) {
      const directory = FIXTURE_DIRECTORY_BY_KIND[kind]!;
      const written = run("python3", ["-c", ENCRYPTION_WRITER, seed, root, kind, directory], { stdio: "inherit" });
      if (written.status !== 0) { failures.push(`${kind}: writer failed`); continue; }
      const cmp = run("bun", [probes, "pdf-encryption-compare", "--input", j(root, directory, BEFORE_FILENAME), "--input", j(root, directory, AFTER_FILENAME)], { encoding: "utf8" });
      if (cmp.status !== 0) { failures.push(`${kind}: reader refused the pair`); continue; }
      if (JSON.parse(cmp.stdout).measurements.equal === true) failures.push(`${kind}: not observable in the encryption projection`);
    }
    for (const failure of failures) console.error(`[generator] ${failure}`);
    return failures.length > 0 ? 1 : 0;
  }
  const entries = [];
  for (const kind of KINDS) {
    const directory = FIXTURE_DIRECTORY_BY_KIND[kind]!;
    const files = [];
    for (const [role, name] of [["base-pdf", BEFORE_FILENAME], ["mutated-pdf", AFTER_FILENAME]] as const) {
      const bytes = read(j(root, directory, name));
      const digest = await crypto.subtle.digest("SHA-256", bytes);
      files.push({ role, path: `../🧫️fixtures/${directory}/${name}`, mediaType: "application/pdf", sha256: `sha256:${[...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("")}`, bytes: bytes.length });
    }
    entries.push({
      schema: "semio.repository-test.fixture/v2",
      id: `encryption-${kind}`,
      class: "third-party-generated",
      target: { artifact: "s.stdio.pdf", standard: "1.7", subset: "vt" },
      mutation: kind,
      outcome: "applied",
