        packageVersion: "0.44",
        engineFamily: "lopdf",
        engineVersion: "0.44",
        command: "bun ✏️s/🔌️plugins/🗄️stdio/🗿️artifacts/📖️pdf/🏅️standards/7️⃣1.7/🪆️subsets/🧾️vt/🏭️generator/📜️script.ts generate",
